#!/usr/bin/env python3
from pwn import *
import re

# Function to extract parameters from the challenge text
def extract_parameters(text):
    parameters = {}
    try:
        # Extract the prime p
        p_match = re.search(r'p = (\d+)', text)
        if p_match:
            parameters['p'] = int(p_match.group(1))

        # Extract a and b for the curve equation
        a_match = re.search(r'a = (\d+)', text)
        if a_match:
            parameters['a'] = int(a_match.group(1))

        b_match = re.search(r'b = (\d+)', text)
        if b_match:
            parameters['b'] = int(b_match.group(1))

        # Extract point coordinates
        x1_match = re.search(r'P1.x = (\d+)', text)
        if x1_match:
            parameters['x1'] = int(x1_match.group(1))

        y1_match = re.search(r'P1.y = (\d+)', text)
        if y1_match:
            parameters['y1'] = int(y1_match.group(1))

        x2_match = re.search(r'P2.x = (\d+)', text)
        if x2_match:
            parameters['x2'] = int(x2_match.group(1))

        y2_match = re.search(r'P2.y = (\d+)', text)
        if y2_match:
            parameters['y2'] = int(y2_match.group(1))
    except Exception as e:
        print(f"Error extracting parameters: {e}")

    return parameters

# Main function to capture the quiz
def main():
    host = "crypto.chal.csaw.io"
    port = 5000

    # Connect to the server
    conn = remote(host, port, level='debug')

    try:
        # Receive all text from the server
        print("Receiving text from the server...")
        all_text = conn.recvall(timeout=10).decode('utf-8', errors='ignore')
        print("\n=== FULL SERVER OUTPUT ===")
        print(all_text)

        # Try to identify different parts of the quiz
        parts = re.split(r'Part \d+', all_text)
        if len(parts) > 1:
            for i, part in enumerate(parts[1:], 1):
                print(f"\n=== PART {i} ===")
                print(part.strip())

                # Extract parameters for this part
                params = extract_parameters(part)
                if params:
                    print(f"Parameters for Part {i}:", params)
        else:
            print("\nCould not identify separate quiz parts.")
            print("Here's the full text again:")
            print(all_text)

            # Try to extract parameters from the whole text
            params = extract_parameters(all_text)
            if params:
                print("Extracted parameters:", params)

    except Exception as e:
        print(f"Error during quiz capture: {e}")

    finally:
        # Try to close the connection if it's still open
        try:
            conn.close()
        except:
            pass

if __name__ == "__main__":
    main()
